import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

// ========== 1. 冷流 Flow：collect 时才执行，每次订阅都独立跑一遍 ==========
fun numbers(): Flow<Int> = flow {
    println(">>> numbers() 开始执行")
    for (i in 1..3) {
        delay(100)            // 模拟网络 / IO 耗时
        emit(i)               // 向下游发射一条数据
    }
}

// ========== 2. StateFlow：永远持有"最新状态"的热流（State 是状态，单数） ==========
class CounterViewModel {
    private val _count = MutableStateFlow(0)          // 内部可变
    val count: StateFlow<Int> = _count.asStateFlow()  // 对外只读，防止外部篡改

    fun increment() {
        _count.value += 1                             // 同步更新状态
    }
}

// ========== 3. SharedFlow：广播"一次性事件"的热流（Event 可复数、可无初值） ==========
class EventBus {
    // replay = 0：不补发历史事件，没订阅者时事件会丢
    private val _events = MutableSharedFlow<String>(replay = 0)
    val events: SharedFlow<String> = _events.asSharedFlow()

    suspend fun post(msg: String) = _events.emit(msg)
}

fun main() = runBlocking {
    // ---- A. 冷流：两个订阅者互不干扰，"开始执行"会打印两次 ----
    val cold = numbers()
    val jobs = listOf(
        launch { cold.collect { println("订阅者A: $it") } },
        launch { cold.collect { println("订阅者B: $it") } }
    )
    jobs.forEach { it.join() }

    // ---- B. StateFlow：新订阅者立刻拿到当前值，相同值会被去重 ----
    val vm = CounterViewModel()
    val stateJob = launch { vm.count.collect { println("UI 状态 = $it") } }
    delay(50)
    vm.increment()
    vm.increment()
    delay(50)
    stateJob.cancel()          // 记得取消，否则 collect 永不结束，runBlocking 不会退出

    // ---- C. SharedFlow：必须先有订阅者，否则事件丢失 ----
    val bus = EventBus()
    val eventJob = launch { bus.events.collect { println("收到事件: $it") } }
    delay(50)
    bus.post("登录成功")
    bus.post("加载完成")
    delay(50)
    eventJob.cancel()

    println("全部演示结束")
}

